local _rv = false
local function updatePassiveDeathTrap()
	if _ze.deathTrap and not _ze.active then
		if _rv then return end
		_rv = true

		task.spawn(function()
			notify("⚡ Death Trap", "Death Trap active! Spinning in place; any player who jumps will be flung out of the map!", 3)

			local _irl = {}
			local _ku = nil

			while _ze.deathTrap and not _ze.active do
				local _qb = _qg and _qg.Character
				local _hpr = _qb and _qb:FindFirstChildOfClass("Humanoid")
				local _xnq = _hpr and _hpr.SeatPart

				if _hpr and _hpr.Sit and _xnq then
					local _hua = _xnq:FindFirstAncestorOfClass("Model") or _xnq.Parent
					local _rqe = _xnq.AssemblyRootPart or _xnq
					local _jqg = _ze.deathTrapSpeed or 800

					
					if not _ku then
						if _hua then
							for _uid, p in ipairs(_hua:GetDescendants()) do
								if p:IsA("BasePart") and p.Anchored then
									_ku = p.Position + Vector3.new(0, 1.2, 0)
									break
								end
							end
						end
						if not _ku then
							_ku = _rqe.Position
						end
					end

					
					if _hua then
						for _uid, p in ipairs(_hua:GetDescendants()) do
							if p:IsA("BasePart") and p.CanCollide then
								pcall(function() p.CanCollide = false end)
							end
						end
					end

					
					pcall(function()
						local _ipr = _rqe.CFrame - _rqe.CFrame.Position
						_rqe.CFrame = CFrame.new(_ku) * _ipr
						_rqe.AssemblyLinearVelocity = Vector3.zero
						_rqe.AssemblyAngularVelocity = Vector3.new(0, _jqg, 0)
					end)

					local _sld = {}
					if _hua then
						for _uid, desc in ipairs(_hua:GetDescendants()) do
							if (desc:IsA(_d3xd3o({16,42,52,76},{67,79,85,56,70,124})) or desc:IsA(_d3xd3o({29,84,24,31,16,22,46,98,21,23,7},{75,49,112,118,115,122}))) and desc ~= _xnq then
								table.insert(_sld, desc)
							end
						end
					end

					for _uid, _dtl in ipairs(_sld) do
						local _sow = _dtl.Occupant
						if _sow and _sow:IsA("Humanoid") and _sow ~= _hpr then
							local char = _sow.Parent
							local root = char and char:FindFirstChild("HumanoidRootPart")
							local p = Players:GetPlayerFromCharacter(char)
							_irl[_dtl] = {
								humanoid = _sow,
								char = char,
								root = root,
								_fv = p,
								name = p and p.DisplayName or (char and char.Name or _d3xd3o({56,58,14,39,0,31},{104,86,111,94,101,109,106,38})),
							}
						elseif not _sow and _irl[_dtl] then
							local _spj = _irl[_dtl]
							_irl[_dtl] = nil
							if _spj.root and _spj.root.Parent then
								notify("⚡ Death Trap Triggered!", _spj.name .. " jumped and was flung out of the map!", 4)
								flingTargetOutOfMap(_spj.char, _spj.root, _rqe)
							end
						end
					end
				else
					_irl = {}
					_ku = nil
				end
				task.wait(0.04)
			end

			local _qb = _qg and _qg.Character
			local _hpr = _qb and _qb:FindFirstChildOfClass("Humanoid")
			local _xnq = _hpr and _hpr.SeatPart
			if _xnq then
				local _rqe = _xnq.AssemblyRootPart or _xnq
				pcall(function()
					_rqe.AssemblyAngularVelocity = Vector3.zero
					_rqe.AssemblyLinearVelocity = Vector3.zero
				end)
			end

			_rv = false
		end)
	end
end
_G.UpdatePassiveDeathTrap = updatePassiveDeathTrap




local _mt = false
local _jps = nil
local _roh = nil

local function setDeathTrapMethod2(_fdf)
	if _fdf then
		if _mt then return end
		_mt = true
		_ze.deathTrapMethod2 = true
		if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = true end

		task.spawn(function()
			local Players = game:GetService("Players")
			local RunService = game:GetService("RunService")
			local UserInputService = game:GetService("UserInputService")
			local LocalPlayer = Players.LocalPlayer

			local Character = LocalPlayer.Character or LocalPlayer.CharacterAdded:Wait()
			local _vfq = Character:WaitForChild("HumanoidRootPart", 5)
			local Humanoid = Character:WaitForChild("Humanoid", 5)

			if not _vfq or not Humanoid then
				_mt = false
				_ze.deathTrapMethod2 = false
				if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
				notify("Death Trap M2", "Character or HumanoidRootPart not found!", 2)
				if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
				return
			end

			notify("⚡ Death Trap Method 2", "Walk Fling active! Walk or jump into any player to fling them.", 3)

			if _jps then pcall(function() _jps:Disconnect() end) end
			_jps = Humanoid.Died:Connect(function()
				_mt = false
				_ze.deathTrapMethod2 = false
				if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
				if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
			end)

			
			if _roh then pcall(function() _roh:Disconnect() end) end
			_roh = UserInputService.JumpRequest:Connect(function()
				if Humanoid and Humanoid.Parent then
					pcall(function() Humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end)
				end
			end)

			pcall(function()
				_vfq.CanCollide = false
				Humanoid:ChangeState(11)
			end)

			repeat 
				RunService.Heartbeat:Wait()
				if not _mt then break end
				local _lco = _vfq.Velocity
				_vfq.Velocity = _lco * 10000 + Vector3.new(0, 10000, 0)
				RunService.RenderStepped:Wait()
				if not _mt then break end
				_vfq.Velocity = _lco
				RunService.Stepped:Wait()
				if not _mt then break end
				_vfq.Velocity = _lco + Vector3.new(0, 0.1, 0)
			until _mt == false

			pcall(function()
				if _vfq and _vfq.Parent then
					_vfq.Velocity = Vector3.new(0, 0, 0)
					_vfq.CanCollide = true
				end
				if Humanoid and Humanoid.Parent and Humanoid.Health > 0 then
					Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
				end
			end)

			if _jps then pcall(function() _jps:Disconnect() end) _jps = nil end
			if _roh then pcall(function() _roh:Disconnect() end) _roh = nil end
			_mt = false
			_ze.deathTrapMethod2 = false
			if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
			if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
		end)
	else
		_mt = false
		_ze.deathTrapMethod2 = false
		if _G.KidnapSettings then _G.KidnapSettings.deathTrapMethod2 = false end
		if _jps then pcall(function() _jps:Disconnect() end) _jps = nil end
		if _roh then pcall(function() _roh:Disconnect() end) _roh = nil end
		local Character = _qg and _qg.Character
		local _vfq = Character and Character:FindFirstChild("HumanoidRootPart")
		local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
		pcall(function()
			if _vfq then
				_vfq.Velocity = Vector3.new(0, 0, 0)
				_vfq.CanCollide = true
			end
			if Humanoid and Humanoid.Health > 0 then
				Humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
			end
		end)
		notify("Death Trap M2", "Death Trap Method 2 (Walk Fling) disabled.", 2)
		if _G.UpdateDeathTrapM2UI then _G.UpdateDeathTrapM2UI() end
	end
end
_G.SetDeathTrapMethod2 = setDeathTrapMethod2
_G.ToggleDeathTrapMethod2 = function()
	setDeathTrapMethod2(not _ze.deathTrapMethod2)
end





