end

_G.StopKidnapTarget = function()
	_ze.active = false
	_ze.loopKidnap = false
	_ze.statusText = _d3xd3o({63,72,51,73,75,48,16,76,57},{124,41,93,42,46,92})
	local _qb = _qg and _qg.Character
	local _hpr = _qb and _qb:FindFirstChildOfClass("Humanoid")
	local _xnq = _hpr and _hpr.SeatPart
	if _xnq then
		local _rqe = _xnq.AssemblyRootPart or _xnq
		pcall(function()
			_rqe.AssemblyAngularVelocity = Vector3.zero
			_rqe.AssemblyLinearVelocity = Vector3.zero
		end)
	end
	if _qb then
		for _uid, _r in ipairs(_qb:GetDescendants()) do
			if _r.Name:find("Kidnap") then
				pcall(function() _r:Destroy() end)
			end
		end
	end
	notify("Kidnape", "Kidnap operations stopped.", 2)
end




