		_yuj.CornerRadius = UDim.new(0, 6)
		_yuj.Parent = btn

		local _oho = 1
		for _g, _r in ipairs(_jte) do
			if _r == _eds then _oho = _g break end
		end

		btn.MouseButton1Click:Connect(function()
			_oho = (_oho % #_jte) + 1
