		    protectAvatar(_zay.Character)
		    _zay.CharacterAdded:Connect(protectAvatar)
		end
		
		Players.PlayerAdded:Connect(function(_zay)
		    protectAvatar(_zay.Character)
		    _zay.CharacterAdded:Connect(protectAvatar)
		end)
		
		
		
		
