		print(string.format("[Snapshot] Ready. Saved %d part colors, lighting, sky, atmosphere & water. Safe to run shaders.", _qys))
		
		
		
		
		local function toRedTint(_xps)
		    local _erf = 0.299 * _xps.R + 0.587 * _xps.G + 0.114 * _xps.B
		    
		    return Color3.new(_erf * 0.9, _erf * 0.65, _erf * 0.65)
		end
		
		local _ksk = {}
		
		local function applyTint(_hk)
		    if not _hk:IsA('BasePart') and not _hk:IsA('Terrain') then return end
		    if _hk.Name == "PandaTile" then return end
		    if _ksk[_hk] then return end
		    if isCharacterPart(_hk) then return end
		
		    _ksk[_hk] = true
		    
		    if _hk:IsA("Terrain") then
		        _hk.WaterColor = Color3.fromRGB(180, 20, 20)
		    else
		        _hk.Color = toRedTint(_hk.Color)
